files.styles.css:
*{
  box-sizing:border-box}
  body{
    margin:0;
    background:#f7f4eb;
    color:#193e30;
    font:16px/1.65 Arial}
    header,footer{
      padding:24px 7%;
      display:flex;
      justify-content:space-between;
      border-bottom:1px solid #ddd6c7}
      nav{
        display:flex;
        gap:22px}
        a{
          color:inherit}
          h1,h2,.logo{
            font-family:Georgia}
            h1{
              font-size:clamp(38px,5vw,72px);
              line-height:1.08}
              h2{
                font-size:36px}
                .logo{
                  font-size:30px;
                  font-weight:bold;
                  text-decoration:none}
                  main{
                    padding:40px 7%}
                    .hero{
                      display:grid;
                      grid-template-columns:1fr 1fr;
                      gap:50px;
                      align-items:center}
                      .hero img{
                        width:100%;
                        height:480px;
                        object-fit:cover;
                        border-radius:8px}
                        .boton,button{
                          display:inline-block;
                          background:#b65b3c;
                          color:white;
                          border:0;
                          border-radius:6px;
                          padding:13px 24px;
                          text-decoration:none;
                          cursor:pointer}
                          .cards{
                            display:grid;
                            grid-template-columns:repeat(3,1fr);
                            gap:24px}
                            .card{
                              border:1px solid #ddd6c7;
                              border-radius:10px;
                              overflow:hidden}
                              .card img{
                                width:100%;
                                height:240px;
                                object-fit:cover}
                                .card div{
                                  padding:20px}
                                  section{
                                    margin-bottom:70px}
                                    input,textarea{
                                      display:block;
                                      width:100%;
                                      padding:12px;
                                      margin:6px 0 18px;
                                      border:1px solid #b6c0b5;
                                      border-radius:5px;
                                      font:inherit}
                                      form{
                                        max-width:560px}
                                        details{
                                          padding:20px;
                                          border-bottom:1px solid #ccc}
                                          summary{
                                            cursor:pointer;
                                            font-weight:bold}
                                            footer{
                                              font-size:13px}
                                              @media(max-width:650px){
                                                header{
                                                  display:block}
                                                  nav{
                                                    flex-wrap:wrap;
                                                    gap:12px}
                                                    .hero,.cards{
                                                      grid-template-columns:1fr}
                                                      .hero img{
                                                        height:300px}
                                                      }

